
CREATE TEMP TABLE br_spec AS SELECT * FROM jsonb_array_elements($SPEC$[{"slug": "shh-tee", "name": "Shh Tee", "price": 69.99, "cat": "apparel", "desc": "Heavyweight oversized tee. Front: neon shoebox \"Not made to fit in. Made to stand out.\" Back: the Benny Rich bucket-hat kid.", "colors": [{"c": "Blue", "img": "shh-tee-blue.jpg"}], "sizes": ["S", "M", "L", "XL", "XXL"], "stock": 10}, {"slug": "cherub-tee", "name": "Cherub Tee", "price": 69.99, "cat": "apparel", "desc": "Oversized acid-wash tee. Small chest monogram, full-back neon cherub with attitude.", "colors": [{"c": "Blue", "img": "cherub-tee-blue.jpg"}], "sizes": ["S", "M", "L", "XL", "XXL"], "stock": 10}, {"slug": "panther-tee", "name": "Panther Tee", "price": 79.99, "cat": "apparel", "desc": "Oversized acid-wash tee with full-front neon-lit panther artwork.", "colors": [{"c": "Blue", "img": "panther-tee-blue.jpg"}, {"c": "Pink", "img": "panther-tee-pink.jpg"}], "sizes": ["S", "M", "L", "XL", "XXL"], "stock": 10}, {"slug": "bust-tee", "name": "Bust Tee", "price": 69.99, "cat": "apparel", "desc": "Oversized tee. Centre-chest logo, full-back neon marble bust on a Benny Rich plinth.", "colors": [{"c": "Blue", "img": "bust-tee-blue.jpg"}], "sizes": ["S", "M", "L", "XL", "XXL"], "stock": 10}, {"slug": "distressed-logo-tee", "name": "Distressed Logo Tee", "price": 79.99, "cat": "apparel", "desc": "Hand-distressed acid-wash tee with the neon Benny Rich wordmark.", "colors": [{"c": "Blue", "img": "distressed-tee-blue.jpg"}, {"c": "Pink", "img": "distressed-tee-pink.jpg"}], "sizes": ["S", "M", "L", "XL", "XXL"], "stock": 10}, {"slug": "f8-tee", "name": "F8 Tee", "price": 74.99, "cat": "apparel", "desc": "Oversized tee. Small chest logo, neon supercar silhouette on the back.", "colors": [{"c": "Blue", "img": "f8-tee-blue.jpg"}, {"c": "Pink", "img": "f8-tee-pink.jpg"}], "sizes": ["S", "M", "L", "XL", "XXL"], "stock": 10}, {"slug": "countach-hoodie", "name": "Countach Hoodie", "price": 129.99, "cat": "apparel", "desc": "Heavyweight oversized hoodie with contrast neon stitching, sleeve monograms and full-back neon supercar.", "colors": [{"c": "Blue", "img": "countach-hoodie-blue.jpg"}, {"c": "Pink", "img": "countach-hoodie-pink.jpg"}], "sizes": ["S", "M", "L", "XL", "XXL"], "stock": 10}, {"slug": "monogram-puffer", "name": "Monogram Puffer", "price": 199.99, "cat": "apparel", "desc": "All-over monogram puffer jacket with sherpa-lined hood and cuffs.", "colors": [{"c": "Pink", "img": "monogram-puffer-pink.jpg"}], "sizes": ["S", "M", "L", "XL", "XXL"], "stock": 5}, {"slug": "br-cap", "name": "BR Cap", "price": 49.99, "cat": "apparel", "desc": "Six-panel cap with embroidered neon Benny Rich logo.", "colors": [{"c": "Blue", "img": "br-cap-blue.jpg"}, {"c": "Pink", "img": "br-cap-pink.jpg"}], "sizes": ["One Size"], "stock": 15}, {"slug": "br-sunglasses", "name": "BR Sunglasses", "price": 119.99, "cat": "accessories", "desc": "Black acetate frame with Benny Rich temple branding.", "colors": [], "sizes": ["One Size"], "stock": 0}, {"slug": "golden-ticket-print", "name": "Golden Ticket Print", "price": 29.99, "cat": "accessories", "desc": "Neon Golden Ticket artwork. Museum-grade print, 50×70 cm.", "colors": [{"c": "Blue", "img": "golden-ticket-print.jpg"}], "sizes": ["50x70 cm"], "stock": 20}, {"slug": "cushion-vault", "name": "Vault Cushion", "price": 49.99, "cat": "home", "desc": "45×45 cm velvet cushion with neon vault-and-fountain artwork.", "colors": [{"c": "Blue", "img": "cushion-vault-blue.jpg"}], "sizes": ["45x45 cm"], "stock": 10}, {"slug": "cushion-rifle", "name": "Floral Rifle Cushion", "price": 49.99, "cat": "home", "desc": "45×45 cm velvet cushion with neon floral rifle artwork.", "colors": [{"c": "Blue", "img": "cushion-rifle-blue.jpg"}], "sizes": ["45x45 cm"], "stock": 10}, {"slug": "cushion-skyline", "name": "Skyline Cushion", "price": 49.99, "cat": "home", "desc": "45×45 cm velvet cushion with neon skyline collage artwork.", "colors": [{"c": "Pink", "img": "cushion-skyline-pink.jpg"}], "sizes": ["45x45 cm"], "stock": 10}, {"slug": "rug-monogram-frame", "name": "Monogram Frame Rug", "price": 249.99, "cat": "home", "desc": "Tufted rug with framed BR monogram. Luxury in every detail.", "colors": [{"c": "Pink", "img": "rug-monogram-frame-pink.jpg"}], "sizes": ["120x180 cm", "160x230 cm"], "stock": 3}, {"slug": "rug-allover", "name": "All-over Monogram Rug", "price": 249.99, "cat": "home", "desc": "Tufted rug with all-over BR monogram pattern.", "colors": [{"c": "Pink", "img": "rug-allover-pink.jpg"}], "sizes": ["120x180 cm", "160x230 cm"], "stock": 3}, {"slug": "runner-champagne", "name": "Champagne Bottle Runner", "price": 349.99, "cat": "home", "desc": "Shaped tufted runner in the form of a Benny Rich champagne bottle, approx. 80×240 cm.", "colors": [{"c": "Pink", "img": "runner-champagne-pink.jpg"}], "sizes": ["80x240 cm"], "stock": 2}, {"slug": "led-lamp-rifle", "name": "LED Acrylic Lamp — Rifle", "price": 89.99, "cat": "lighting", "desc": "Laser-engraved acrylic panel on an RGB LED base. Switch between blue, pink and more.", "colors": [{"c": "RGB", "img": "led-lamp-rifle.jpg"}], "sizes": ["One Size"], "stock": 10}, {"slug": "led-lamp-rolls", "name": "LED Acrylic Lamp — Coupé", "price": 89.99, "cat": "lighting", "desc": "Laser-engraved acrylic panel with luxury coupé outline on an RGB LED base.", "colors": [{"c": "Blue", "img": "led-lamp-rolls-blue.jpg"}, {"c": "Pink", "img": "led-lamp-rolls-pink.jpg"}], "sizes": ["One Size"], "stock": 10}, {"slug": "br-vodka-700ml", "name": "Benny Rich Vodka 700ml", "price": 69.99, "cat": "beverages", "desc": "Premium vodka in a matte black bottle with neon diamond label. 40% vol. 18+ only.", "colors": [{"c": "Blue", "img": "vodka-blue.jpg"}, {"c": "Pink", "img": "vodka-pink.jpg"}], "sizes": ["700 ml"], "stock": 0}]$SPEC$::jsonb) AS s(j);
-- categories
INSERT INTO categories (tenant_id,name,slug,sort_order,is_active) VALUES
 ('6dc06df8-d871-4424-a3a4-22fc446ea64a','Apparel','apparel',1,true),('6dc06df8-d871-4424-a3a4-22fc446ea64a','Accessories','accessories',2,true),('6dc06df8-d871-4424-a3a4-22fc446ea64a','Home','home',3,true),('6dc06df8-d871-4424-a3a4-22fc446ea64a','Lighting','lighting',4,true),('6dc06df8-d871-4424-a3a4-22fc446ea64a','Beverages','beverages',5,true)
ON CONFLICT (tenant_id,slug) DO NOTHING;
-- products
INSERT INTO products (tenant_id,name,slug,description,price,stock,track_inventory,images,featured_image,category_id,is_active,requires_shipping,product_type,tags,vendor)
SELECT '6dc06df8-d871-4424-a3a4-22fc446ea64a', j->>'name', j->>'slug', j->>'desc', (j->>'price')::numeric,
  (j->>'stock')::int * GREATEST(1, jsonb_array_length(j->'colors')) * jsonb_array_length(j->'sizes'),
  true,
  NULLIF((SELECT array_agg('https://gczmfcabnoofnmfpzeop.supabase.co/storage/v1/object/public/product-images/6dc06df8-d871-4424-a3a4-22fc446ea64a/'||(c->>'img') ORDER BY o) FROM jsonb_array_elements(j->'colors') WITH ORDINALITY x(c,o)), '{}'::text[]),
  (SELECT 'https://gczmfcabnoofnmfpzeop.supabase.co/storage/v1/object/public/product-images/6dc06df8-d871-4424-a3a4-22fc446ea64a/'||(c->>'img') FROM jsonb_array_elements(j->'colors') c LIMIT 1),
  cat.id, true, true, 'physical',
  COALESCE((SELECT array_agg(lower(c->>'c')) FROM jsonb_array_elements(j->'colors') c), '{}'::text[]),
  'Benny Rich'
FROM br_spec JOIN categories cat ON cat.tenant_id='6dc06df8-d871-4424-a3a4-22fc446ea64a' AND cat.slug=j->>'cat'
ON CONFLICT (tenant_id,slug) DO NOTHING;
-- product_categories
INSERT INTO product_categories (product_id,category_id,is_primary,sort_order)
SELECT p.id, p.category_id, true, 0 FROM products p WHERE p.tenant_id='6dc06df8-d871-4424-a3a4-22fc446ea64a' AND p.category_id IS NOT NULL
ON CONFLICT DO NOTHING;
-- variants (color x size; products without colors get size-only variants)
INSERT INTO product_variants (product_id,tenant_id,title,sku,price,stock,track_inventory,image_url,attribute_values,position,is_active)
SELECT p.id,'6dc06df8-d871-4424-a3a4-22fc446ea64a',
  concat_ws(' / ', c.c->>'c', s.sz),
  'BR-'||upper(p.slug)||'-'||upper(COALESCE(left(c.c->>'c',2),'X'))||'-'||upper(replace(replace(s.sz,' ',''),'x','X')),
  (b.j->>'price')::numeric, (b.j->>'stock')::int, true,
  CASE WHEN c.c IS NULL THEN NULL ELSE 'https://gczmfcabnoofnmfpzeop.supabase.co/storage/v1/object/public/product-images/6dc06df8-d871-4424-a3a4-22fc446ea64a/'||(c.c->>'img') END,
  jsonb_strip_nulls(jsonb_build_object('Color', c.c->>'c', 'Size', s.sz)),
  row_number() OVER (PARTITION BY p.id ORDER BY c.o NULLS FIRST, s.o), true
FROM br_spec b
JOIN products p ON p.tenant_id='6dc06df8-d871-4424-a3a4-22fc446ea64a' AND p.slug=b.j->>'slug'
LEFT JOIN LATERAL jsonb_array_elements(b.j->'colors') WITH ORDINALITY c(c,o) ON true
JOIN LATERAL jsonb_array_elements_text(b.j->'sizes') WITH ORDINALITY s(sz,o) ON true
WHERE NOT EXISTS (SELECT 1 FROM product_variants v WHERE v.product_id=p.id);
SELECT (SELECT count(*) FROM categories WHERE tenant_id='6dc06df8-d871-4424-a3a4-22fc446ea64a') cats,(SELECT count(*) FROM products WHERE tenant_id='6dc06df8-d871-4424-a3a4-22fc446ea64a') products,(SELECT count(*) FROM product_variants WHERE tenant_id='6dc06df8-d871-4424-a3a4-22fc446ea64a') variants,(SELECT count(*) FROM product_categories pc JOIN products p ON p.id=pc.product_id WHERE p.tenant_id='6dc06df8-d871-4424-a3a4-22fc446ea64a') pcs;
